contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public function holding the test logic
    function run(address from, address caddress, address[] calldata _tos, uint v) public payable {
        require(_tos.length > 0);

        bool reverted;
        bool ret;
        try c.transfer(from, caddress, _tos, v) returns (bool r) {
            reverted = false;
            ret = r;
        } catch {
            reverted = true;
            ret = false;
        }

        // General rule: when _tos.length > 0 the call must not revert and must return true
        assert(!reverted && ret == true);
    }

    receive() external payable {}
}

